CREATE TABLE IF NOT EXISTS manufacturer(id varchar(32) PRIMARY KEY,code varchar(20) NOT NULL,name varchar(100) NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS treatment(id varchar(32) PRIMARY KEY,code varchar(20) NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS cloth_type(id varchar(32) PRIMARY KEY,code varchar(20) NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS cloth_weight(id varchar(32) PRIMARY KEY,type_id varchar(32) REFERENCES cloth_type(id),cloth_code varchar(20) NOT NULL,weight numeric(12,3) NOT NULL,unit varchar(20) NOT NULL DEFAULT 'g/m2',active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS width_ref(id varchar(32) PRIMARY KEY,width numeric(12,3) NOT NULL,unit varchar(20) NOT NULL DEFAULT 'mm',active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS form_ref(id varchar(32) PRIMARY KEY,code varchar(20) NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS grade_ref(id varchar(32) PRIMARY KEY,code varchar(20) NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS cloth(id varchar(80) PRIMARY KEY,weight_id varchar(32),manufacturer_id varchar(32),treatment_id varchar(32),width_id varchar(32),form_id varchar(32),grade_id varchar(32),material_no varchar(128),status varchar(20) NOT NULL DEFAULT 'ACTIVE',remarks text,version bigint NOT NULL DEFAULT 1,updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS duplicate_ref(id varchar(32) PRIMARY KEY,business_key varchar(32),value varchar(20));
CREATE TABLE IF NOT EXISTS flat_material(id varchar(80) PRIMARY KEY,category varchar(80) NOT NULL,data jsonb NOT NULL,material_no varchar(128),version bigint NOT NULL DEFAULT 1,updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS downstream_item(material_no varchar(128) PRIMARY KEY,data jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS downstream_bom(parent_no varchar(128) REFERENCES downstream_item,child_no varchar(128) REFERENCES downstream_item,quantity numeric,PRIMARY KEY(parent_no,child_no));
CREATE TABLE IF NOT EXISTS downstream_routing(material_no varchar(128) REFERENCES downstream_item,version bigint,data jsonb,PRIMARY KEY(material_no,version));
